import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

cross_entropy_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void cross_entropy_forward_kernel(
    const float* predictions,
    const long* targets,
    float* losses,
    int batch_size,
    int num_classes) {

    int row = blockIdx.x;
    if (row >= batch_size) return;

    int target = targets[row];
    const float* row_preds = predictions + row * num_classes;

    // Step 1: Find max for numerical stability
    float max_val = -1e38f;
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        max_val = fmaxf(max_val, row_preds[i]);
    }

    // Block reduction for max
    extern __shared__ float shared_mem[];
    float* s_max = shared_mem;
    s_max[threadIdx.x] = max_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_max[threadIdx.x] = fmaxf(s_max[threadIdx.x], s_max[threadIdx.x + s]);
        }
        __syncthreads();
    }
    max_val = s_max[0];
    __syncthreads();

    // Step 2: Compute sum of exp(x - max)
    float sum_exp = 0.0f;
    for (int i = threadIdx.x; i < num_classes; i += blockDim.x) {
        sum_exp += expf(row_preds[i] - max_val);
    }

    // Block reduction for sum
    float* s_sum = shared_mem;
    s_sum[threadIdx.x] = sum_exp;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        }
        __syncthreads();
    }
    sum_exp = s_sum[0];

    // Step 3: Compute final loss for the row
    if (threadIdx.x == 0) {
        float log_sum_exp = logf(sum_exp) + max_val;
        losses[row] = log_sum_exp - row_preds[target];
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    int batch_size = predictions.size(0);
    int num_classes = predictions.size(1);

    auto losses = torch::empty({batch_size}, predictions.options());

    int threads_per_block = 256;
    int shared_mem_size = threads_per_block * sizeof(float);

    cross_entropy_forward_kernel<<<batch_size, threads_per_block, shared_mem_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<long>(),
        losses.data_ptr<float>(),
        batch_size,
        num_classes
    );

    return losses.mean();
}
"""

cross_entropy_lib = load_inline(
    name="cross_entropy_lib",
    cpp_sources=cross_entropy_kernel_source,
    functions=["cross_entropy_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cross_entropy_lib = cross_entropy_lib

    def forward(self, predictions, targets):
        return self.cross_entropy_lib.cross_entropy_hip(predictions, targets)

