#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out) {

    int n = blockIdx.x / C;
    int c = blockIdx.x % C;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;

    if (n < N && c < C && h_out < H_out && w_out < W_out) {
        float sum = 0.0f;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        for (int kh = 0; kh < K; ++kh) {
            for (int kw = 0; kw < K; ++kw) {
                int h_in = h_start + kh;
                int w_in = w_start + kw;

                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    float val = input[((n * C + c) * H + h_in) * W + w_in];
                    float w_val = weight[(c * K + kh) * K + kw];
                    sum += val * w_val;
                }
            }
        }
        if (bias) {
            sum += bias[c];
        }
        output[((n * C + c) * H_out + h_out) * W_out + w_out] = sum;
    }
}

torch::Tensor depthwise_conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    at::optional<torch::Tensor> bias,
    int stride,
    int padding) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int K = weight.size(2);

    int H_out = (H + 2 * padding - K) / stride + 1;
    int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    dim3 block_size(1, 1, 1); // We'll adjust this for better performance
    // For now, let's just make it work correctly.
    // However, HIP kernels with (1, 1, 1) are very slow.
    // Better: use a grid that covers N*C, H_out, W_out.

    // We'll rethink the indexing to get better occupancy.
    return output;
}
"""

# Let's write a better kernel.
depthwise_conv2d_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c = (idx / (W_out * H_out)) % C;
        int n = idx / (W_out * H_out * C);

        float sum = 0.0f;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_start + kh;
            if (h_in >= 0 && h_in < H) {
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_start + kw;
                    if (w_in >= 0 && w_in < W) {
                        float val = input[((n * C + c) * H + h_in) * W + w_in];
                        float w_val = weight[(c * K + kh) * K + kw];
                        sum += val * w_val;
                    }
                }
            }
        }
        if (bias) {
            sum += bias[c];
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    at::optional<torch::Tensor> bias,
    int stride,
    int padding) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int K = weight.size(2);

    int H_out = (H + 2 * padding - K) / stride + 1;
    int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());
    int total_elements = N * C * H_out * W_out;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    float* bias_ptr = bias.has_value() ? bias.value().data_ptr<float>() : nullptr;

    hipLaunchKernelGGL(depthwise_conv2d_kernel, dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        K, stride, padding,
        H_out, W_out);

    return output;
}
"""

depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    functions=["depthwise_conv2d_hip"],
    verbose=True,
