sum_reduction_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void sum_reduction_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                    int M, int D, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = M * N;

    if (idx < total_elements) {
        int m = idx / N;
        int n = idx % N;

        float sum = 0.0f;
        int base_idx = m * D * N + n;
        for (int i = 0; i < D; ++i) {
            sum += input[base_idx + i * N];
        }
        output[idx] = sum;
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    int ndim = input.dim();

    // Handle negative dimension
    if (dim < 0) dim += ndim;

    int M = 1;
    for (int i = 0; i < dim; ++i) {
        M *= sizes[i];
    }

    int D = sizes[dim];

    int N = 1;
    for (int i = dim + 1; i < ndim; ++i) {
        N *= sizes[i];
    }

    auto output_shape = sizes.vec();
    output_shape[dim] = 1;
    auto output = torch::empty(output_shape, input.options());

    int total_output_elements = M * N;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    sum_reduction_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        M, D, N
    );

    return output;
}
"""

sum_reduction_lib = load_inline(
    name="sum_reduction_lib",
    cpp_sources=sum_reduction_source,
    functions=["sum_reduction_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return sum_reduction_lib.sum_reduction_hip(x, self.dim)

