layernorm_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

template <typename T>
__device__ void block_reduce_sum(T* val, int tid, int block_size) {
    for (int offset = block_size / 2; offset > 0; offset /= 2) {
        if (tid < offset) {
            val[tid] += val[tid + offset];
        }
        __syncthreads();
    }
}

__global__ void layernorm_kernel(const float* x, const float* weight, const float* bias, float* out, int N, int M, float eps) {
    // x: (N, M), weight: (M), bias: (M), out: (N, M)
    // Each block handles one row (size M)
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int block_dim = blockDim.x;

    extern __shared__ float shared_mem[];
    float* shared_sum = shared_mem;
    float* shared_sq_sum = shared_mem + block_dim;

    float local_sum = 0;
    float local_sq_sum = 0;

    for (int i = tid; i < M; i += block_dim) {
        float val = x[row * M + i];
        local_sum += val;
        local_sq_sum += val * val;
    }

    shared_sum[tid] = local_sum;
    shared_sq_sum[tid] = local_sq_sum;
    __syncthreads();

    // Block reduction
    for (int offset = block_dim / 2; offset > 0; offset /= 2) {
        if (tid < offset) {
            shared_sum[tid] += shared_sum[tid + offset];
            shared_sq_sum[tid] += shared_sq_sum[tid + offset];
        }
        __syncthreads();
    }

    float mean = shared_sum[0] / M;
    float var = (shared_sq_sum[0] / M) - (mean * mean);
    float inv_std = 1.0f / sqrtf(var + eps);

    for (int i = tid; i < M; i += block_dim) {
        int idx = row * M + i;
        out[idx] = (x[idx] - mean) * inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_hip(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float eps) {
    auto input_shape = x.sizes();
    int N = input_shape[0];
    int M = 1;
    for (int i = 1; i < input_shape.size(); ++i) {
        M *= input_shape[i];
    }

    auto out = torch::empty_like(x);

    const int block_size = 512;
    int shared_mem_size = 2 * block_size * sizeof(float);

    layernorm_kernel<<<N, block_size, shared_mem_size>>>(
        x.data_ptr<float>(), 
        weight.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        out.data_ptr<float>(), 
        N, M, eps
    );

    return out;
}
"""

layernorm_cpp_source = """
torch::Tensor layernorm_hip(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float eps);
"""

layernorm_lib = load_inline(
