class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Check if input's last dimensions match normalized_shape
        # Flatten x to (N, M) where M is the product of normalized_shape
        # For simplicity in this implementation, assume x's tail matches normalized_shape

        # Original input shape
        original_shape = x.shape

        # Calculate M from normalized_shape
        M = 1
        for s in self.normalized_shape:
            M *= s

        # Calculate N
        total_elements = x.numel()
        N = total_elements // M

        # Reshape x to (N, M)
        x_reshaped = x.view(N, M)

        # Flatten weight and bias
        weight_flat = self.weight.view(-1)
        bias_flat = self.bias.view(-1)

        # Apply layernorm
        out = layernorm_lib.layernorm_hip(x_reshaped, weight_flat, bias_flat, self.eps)

        # Reshape back
        return out.view(original_shape)

