rms_norm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void rms_norm_kernel(const float* x, float* out, int N, int C, int H, int W, float eps) {
    int idx = blockIdx.x * (int)blockDim.x + threadIdx.x;
    int num_nhw = N * H * W;
    if (idx < num_nhw) {
        int w = idx % W;
        int h = (idx / W) % H;
        int n = idx / (H * W);

        int stride = H * W;
        int base_idx = n * C * stride + h * W + w;

        float sum_sq = 0;
        for (int c = 0; c < C; ++c) {
            float val = x[base_idx + c * stride];
            sum_sq += val * val;
        }

        float inv_rms = 1.0f / rsqrtf(sum_sq / C + eps); // Wait, rsqrtf(x) is 1/sqrt(x), so 1/rsqrtf(x) is sqrt(x). Correct is 1/sqrt(x) = rsqrt(x).
        // Let's use rsqrtf directly.
        inv_rms = rsqrtf(sum_sq / (float)C + eps);

        for (int c = 0; c < C; ++c) {
            out[base_idx + c * stride] = x[base_idx + c * stride] * inv_rms;
        }
    }
}

torch::Tensor rms_norm_hip(torch::Tensor x, float eps) {
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);

    auto out = torch::empty_like(x);

    int num_nhw = N * H * W;
    const int block_size = 256;
    const int num_blocks = (num_nhw + block_size - 1) / block_size;

    rms_norm_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), 
        out.data_ptr<float>(), 
        (int)N, (int)C, (int)H, (int)W, 
        eps
    );

    return out;
}
