softmax_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>
#include <cmath>

#define BLOCK_SIZE 1024

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_input = input + row * dim;
    float* row_output = output + row * dim;

    // Step 1: Find max
    float thread_max = -INFINITY;
    for (int i = threadIdx.x; i < dim; i += BLOCK_SIZE) {
        thread_max = fmaxf(thread_max, row_input[i]);
    }

    // Block-level reduction for max
    __shared__ float shared_max[BLOCK_SIZE];
    shared_max[threadIdx.x] = thread_max;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_max[threadIdx.x] = fmaxf(shared_max[threadIdx.x], shared_max[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    float row_max = shared_max[0];

    // Step 2: Find sum of exp(x - row_max)
    float thread_sum = 0.0f;
    for (int i = threadIdx.x; i < dim; i += BLOCK_SIZE) {
        thread_sum += expf(row_input[i] - row_max);
    }

    // Block-level reduction for sum
    __shared__ float shared_sum[BLOCK_SIZE];
    shared_sum[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float row_sum = shared_sum[0];

    // Step 3: Compute final softmax
    for (int i = threadIdx.x; i < dim; i += BLOCK_SIZE) {
        row_output[i] = expf(row_input[i] - row_max) / row_sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);
    auto y = torch::empty_like(x);

    const int num_blocks = batch_size;
    const int threads_per_block = BLOCK_SIZE;

    softmax_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        dim
    );

    return y;
}
"""

