#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void tall_skinny_matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Each thread computes one element of C
    // C is M x N, A is M x K, B is K x N
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

// Optimized version with shared memory tiling
__global__ void tall_skinny_matmul_tiled_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    // Using a block size of TILE_SIZE x TILE_SIZE
    const int TILE_SIZE = 16;
    __shared__ float sA[TILE_SIZE][32]; // Assuming K <= 32
    __shared__ float sB[32][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float sum = 0.0f;

    // We can iterate over K in chunks of 32
    for (int k_offset = 0; k_offset < K; k_offset += 32) {
        // Load A into shared memory
        if (row < M && (k_offset + tx) < K) {
            sA[ty][tx] = A[row * K + (k_offset + tx)];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // Load B into shared memory
        // Wait, the tx and ty loading logic for B should be careful
        // sB is 32 x TILE_SIZE
        if (col < N && (k_offset + ty) < K) {
            sB[ty][tx] = B[(k_offset + ty) * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute
        for (int k = 0; k < 32 && (k_offset + k) < K; ++k) {
            sum += sA[ty][k] * sB[k][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

// Even more optimized: Tiling + Register blocking
// Let's keep it simple first and see if it's faster than torch.matmul

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + block_size.x - 1) / block_size.x, (M + block_size.y - 1) / block_size.y);

    if (K <= 32) {
        tall_skinny_matmul_tiled_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
    } else {
        tall_skinny_matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
    }

    return C;
}
"""

