#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <algorithm>
#include <float.h>

__global__ void maxpool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int k_h, int k_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int H_out, int W_out)
{
    // x-dimension: W_out
    // y-dimension: H_out
    // z-dimension: N * C

    int w_out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int h_out_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int nc_idx = blockIdx.z;

    if (w_out_idx < W_out && h_out_idx < H_out) {
        int n_idx = nc_idx / C;
        int c_idx = nc_idx % C;

        int h_start = h_out_idx * stride_h - padding_h;
        int w_start = w_out_idx * stride_w - padding_w;

        float max_val = -FLT_MAX;

        const float* input_ptr = input + (n_idx * C + c_idx) * H * W;

        for (int kh = 0; kh < k_h; ++kh) {
            int h_in = h_start + kh * dilation_h;
            if (h_in >= 0 && h_in < H) {
                for (int kw = 0; kw < k_w; ++kw) {
                    int w_in = w_start + kw * dilation_w;
                    if (w_in >= 0 && w_in < W) {
                        float val = input_ptr[h_in * W + w_in];
                        if (val > max_val) {
                            max_val = val;
                        }
                    }
                }
            }
        }
        output[(nc_idx * H_out + h_out_idx) * W_out + w_out_idx] = max_val;
    }
}

torch::Tensor maxpool2d_hip(
    torch::Tensor input,
    int kernel_size, int stride, int padding, int dilation) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int k_h = kernel_size;
    int k_w = kernel_size;
    int stride_h = stride;
    int stride_w = stride;
    int padding_h = padding;
    int padding_w = padding;
    int dilation_h = dilation;
    int dilation_w = dilation;

    int H_out = (H + 2 * padding_h - dilation_h * (k_h - 1) - 1) / stride_h + 1;
    int W_out = (W + 2 * padding_w - dilation_w * (k_w - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((W_out + block_size.x - 1) / block_size.x,
                    (H_out + block_size.y - 1) / block_size.y,
                    N * C);

    maxpool2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        k_h, k_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        H_out, W_out
    );

    return output;
}
