        reinterpret_cast<float4*>(output)[idx / 4] = out_vec;
    } else {
        for (int i = idx; i < n; ++i) {
            float x = input[i];
            output[i] = 0.5f * x * (1.0f + erf(x * 0.7071067811865475f));
