cross_entropy_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

struct Result {
    float max_val;
    float sum_exp;
};

__device__ __forceinline__ Result combine(Result a, Result b) {
    Result res;
    res.max_val = fmaxf(a.max_val, b.max_val);
    res.sum_exp = a.sum_exp * expf(a.max_val - res.max_val) + b.sum_exp * expf(b.max_val - res.max_val);
    return res;
}

__device__ __forceinline__ Result warpReduce(Result res) {
    for (int offset = 32; offset > 0; offset /= 2) {
        Result other;
        other.max_val = __shfl_xor(res.max_val, offset, 64);
        other.sum_exp = __shfl_xor(res.sum_exp, offset, 64);
        res = combine(res, other);
    }
    return res;
}

__global__ void cross_entropy_forward_kernel_online(
    const float4* predictions,
    const long* targets,
    float* losses,
    int batch_size,
    int num_classes_v4) {

    int row = blockIdx.x;
    if (row >= batch_size) return;

    int target = targets[row];
    const float4* row_preds_v4 = predictions + row * num_classes_v4;

    Result res = {-1e38f, 0.0f};

    for (int i = threadIdx.x; i < num_classes_v4; i += blockDim.x) {
        float4 p = row_preds_v4[i];
        Result r4;
        r4.max_val = fmaxf(p.x, fmaxf(p.y, fmaxf(p.z, p.w)));
        r4.sum_exp = expf(p.x - r4.max_val) + expf(p.y - r4.max_val) + expf(p.z - r4.max_val) + expf(p.w - r4.max_val);
        res = combine(res, r4);
    }

    res = warpReduce(res);

    static __shared__ float shared_max[8];
    static __shared__ float shared_sum[8];
    int lane = threadIdx.x % 64;
    int wid = threadIdx.x / 64;

    if (lane == 0) {
        shared_max[wid] = res.max_val;
        shared_sum[wid] = res.sum_exp;
    }
    __syncthreads();

    if (wid == 0) {
        res.max_val = (threadIdx.x < (blockDim.x / 64)) ? shared_max[threadIdx.x] : -1e38f;
        res.sum_exp = (threadIdx.x < (blockDim.x / 64)) ? shared_sum[threadIdx.x] : 0.0f;
        res = warpReduce(res);
        if (threadIdx.x == 0) {
            shared_max[0] = res.max_val;
            shared_sum[0] = res.sum_exp;
        }
    }
    __syncthreads();
    float max_val = shared_max[0];
    float sum_exp = shared_sum[0];

    if (threadIdx.x == 0) {
        const float* row_preds = reinterpret_cast<const float*>(row_preds_v4);
        float log_sum_exp = logf(sum_exp) + max_val;
        losses[row] = log_sum_exp - row_preds[target];
    }
}

