#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void __launch_bounds__(256)
sum_reduction_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                    size_t M, size_t D, size_t N) {
    size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t total_elements = M * N;

    if (idx < total_elements) {
        size_t m = idx / N;
        size_t n = idx % N;

        float sum = 0.0f;
        size_t base_idx = m * D * N + n;
        const float* ptr = &input[base_idx];

        // Unroll loop for better performance and use pointer arithmetic
        size_t i = 0;
        for (; i + 7 < D; i += 8) {
            sum += ptr[0];
            sum += ptr[N];
            sum += ptr[2 * N];
            sum += ptr[3 * N];
            sum += ptr[4 * N];
            sum += ptr[5 * N];
            sum += ptr[6 * N];
            sum += ptr[7 * N];
            ptr += 8 * N;
        }
        for (; i < D; ++i) {
            sum += *ptr;
            ptr += N;
        }
        output[idx] = sum;
    }
}

torch::Tensor sum_reduction_hip(torch::Tensor input, int dim) {
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    auto sizes = input.sizes();
    int ndim = input.dim();

    if (dim < 0) dim += ndim;

    size_t M = 1;
    for (int i = 0; i < dim; ++i) {
        M *= sizes[i];
    }

    size_t D = (size_t)sizes[dim];

    size_t N = 1;
    for (int i = dim + 1; i < ndim; ++i) {
        N *= sizes[i];
    }

    auto output_shape = sizes.vec();
    output_shape[dim] = 1;
    auto output = torch::empty(output_shape, input.options());

    size_t total_output_elements = M * N;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    sum_reduction_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        M, D, N
    );

    return output;
}
"""

