matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hipblas/hipblas.h>

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    hipblasHandle_t handle;
    hipblasCreate(&handle);

    float alpha = 1.0f;
    float beta = 0.0f;

    // hipblasSgemm expects column-major order.
    // PyTorch tensors are row-major.
    // A * B = C  (row-major)
    // C^T = (A * B)^T = B^T * A^T (column-major)
    // In hipblasSgemm:
    // C = alpha * op(A) * op(B) + beta * C
    // We want C_row = A_row * B_row
    // This is equivalent to C_col^T = (A_row * B_row)^T = B_row^T * A_row^T
    // If we treat row-major matrices as column-major:
    // A_row (M, K) becomes A'_col (K, M)
    // B_row (K, N) becomes B'_col (N, K)
    // C_row (M, N) becomes C'_col (N, M)
    // We want C'_col(N, M) = B'_col(N, K) * A'_col(K, M)

    hipblasSgemm(handle,
                 HIPBLAS_OP_N, HIPBLAS_OP_N,
                 N, M, K,
                 &alpha,
                 B.data_ptr<float>(), N,
                 A.data_ptr<float>(), K,
                 &beta,
                 C.data_ptr<float>(), N);

    hipblasDestroy(handle);

    return C;
}
"""

