#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void mv_kernel_vec(const float4* __restrict__ A, const float4* __restrict__ B, float* __restrict__ C, int M, int K_vec) {
    int row = blockIdx.x;
    if (row >= M) return;

    extern __shared__ float shared_mem[];
    float sum = 0.0f;
    int tid = threadIdx.x;

    for (int k = tid; k < K_vec; k += blockDim.x) {
        float4 a = A[row * K_vec + k];
        float4 b = B[k];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    shared_mem[tid] = sum;
    __syncthreads();

    // Use warp reduction for faster reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] += shared_mem[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        C[row] = shared_mem[0];
    }
}

torch::Tensor mv_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());

    int K_vec = K / 4;
    const int threads_per_block = 256;
    const int shared_mem_size = threads_per_block * sizeof(float);

    mv_kernel_vec<<<M, threads_per_block, shared_mem_size>>>(
        (const float4*)A.data_ptr<float>(),
        (const float4*)B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K_vec
    );

    return C;
}
"""

