# Optimized Batched Matrix Multiplication using hipBLAS directly from C++
# This avoids some of the PyTorch overhead.
bmm_cpp_source = """
#include <torch/extension.h>
#include <hipblas/hipblas.h>
#include <hip/hip_runtime.h>

// Global hipblas handle
hipblasHandle_t get_handle() {
    static hipblasHandle_t handle = nullptr;
    if (handle == nullptr) {
        hipblasCreate(&handle);
    }
    return handle;
}

torch::Tensor bmm_hip(torch::Tensor A, torch::Tensor B) {
    int batch_size = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int N = B.size(2);

    auto C = torch::empty({batch_size, M, N}, A.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    // hipBLAS uses column-major by default, but we can handle row-major
    // A is (batch, M, K) row-major -> (batch, K, M) column-major
    // B is (batch, K, N) row-major -> (batch, N, K) column-major
    // We want C = A * B (row-major (batch, M, N))
    // In column-major: C^T = B^T * A^T
    // B^T is (batch, N, K) column-major
    // A^T is (batch, K, M) column-major
    // C^T is (batch, N, M) column-major

    hipblasSgemmStridedBatched(
        get_handle(),
        HIPBLAS_OP_N, HIPBLAS_OP_N,
        N, M, K,
        &alpha,
        B.data_ptr<float>(), N, K * N,
        A.data_ptr<float>(), K, M * K,
        &beta,
        C.data_ptr<float>(), N, M * N,
        batch_size
    );

    return C;
}
"""

