#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_SIZE 32

__global__ void tall_skinny_matmul_tiled_v2_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int k_offset = 0; k_offset < K; k_offset += TILE_SIZE) {
        // Load A into shared memory
        if (row < M && (k_offset + tx) < K) {
            sA[ty][tx] = A[row * K + (k_offset + tx)];
        } else {
            sA[ty][tx] = 0.0f;
        }

        // Load B into shared memory
        if (col < N && (k_offset + ty) < K) {
            sB[ty][tx] = B[(k_offset + ty) * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += sA[ty][k] * sB[k][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    if (A.is_cuda() == false) A = A.cuda();
    if (B.is_cuda() == false) B = B.cuda();

    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 num_blocks((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    tall_skinny_matmul_tiled_v2_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
"""

