matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hipblas/hipblas.h>

static hipblasHandle_t global_handle = nullptr;

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    if (global_handle == nullptr) {
        hipblasCreate(&global_handle);
    }

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    hipblasSgemm(global_handle,
                 HIPBLAS_OP_N, HIPBLAS_OP_N,
                 N, M, K,
                 &alpha,
                 B.data_ptr<float>(), N,
                 A.data_ptr<float>(), K,
                 &beta,
                 C.data_ptr<float>(), N);

    return C;
}
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=matmul_cpp_source,
    functions=["matmul_hip"],
    verbose=True,
    extra_ldflags=["-lhipblas"],
)

