mv_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define THREADS_PER_BLOCK 512

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

__global__ void mv_kernel_vec(const float4* __restrict__ A, const float4* __restrict__ B, float* __restrict__ C, int M, int K_vec) {
    int row = blockIdx.x;
    if (row >= M) return;

    float sum = 0.0f;
    int tid = threadIdx.x;

    // Manual unrolling might help, but let's start with basic vectorized and warp reduction
    for (int k = tid; k < K_vec; k += THREADS_PER_BLOCK) {
        float4 a = A[row * K_vec + k];
        float4 b = B[k];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    // Block reduction
    static __shared__ float shared_sum[32]; // 512 threads / 64 (warp size on ROCm) = 8 warps
    // Wait, ROCm warp size is 64.
    int warpId = tid / 64;
    int lane = tid % 64;

    // Warp reduction sum
    float val = sum;
    for (int offset = 32; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);

    if (lane == 0) shared_sum[warpId] = val;
    __syncthreads();

    if (tid < 64) {
        val = (tid < (THREADS_PER_BLOCK / 64)) ? shared_sum[tid] : 0.0f;
        for (int offset = 32; offset > 0; offset /= 2)
            val += __shfl_down(val, offset);
        if (tid == 0) C[row] = val;
    }
}

torch::Tensor mv_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());

    int K_vec = K / 4;
    const int threads_per_block = THREADS_PER_BLOCK;

    mv_kernel_vec<<<M, threads_per_block>>>(
        (const float4*)A.data_ptr<float>(),
        (const float4*)B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K_vec
    );

    return C;
}
"""

mv_module = load_inline(
    name="mv_module",
    cpp_sources=mv_cpp_source,
    functions=["mv_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.mv_module = mv_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.mv_module.mv_hip(A, B)

