softmax_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

#define BLOCK_SIZE 1024

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_input = input + row * dim;
    float* row_output = output + row * dim;

    float thread_max = -INFINITY;
    float thread_sum = 0.0f;

    // Use float4 for vectorized loads
    const float4* row_input_v4 = reinterpret_cast<const float4*>(row_input);
    int dim_v4 = dim / 4;

    for (int i = threadIdx.x; i < dim_v4; i += BLOCK_SIZE) {
        float4 vals = row_input_v4[i];
        float row_vals[4] = {vals.x, vals.y, vals.z, vals.w};
        for (int j = 0; j < 4; j++) {
            float val = row_vals[j];
            if (val > thread_max) {
                thread_sum = thread_sum * expf(thread_max - val) + 1.0f;
                thread_max = val;
            } else {
                thread_sum += expf(val - thread_max);
            }
        }
    }

    // Handle remaining elements if dim is not a multiple of 4 (though in our case it is)
    for (int i = dim_v4 * 4 + threadIdx.x; i < dim; i += BLOCK_SIZE) {
        float val = row_input[i];
        if (val > thread_max) {
            thread_sum = thread_sum * expf(thread_max - val) + 1.0f;
            thread_max = val;
        } else {
            thread_sum += expf(val - thread_max);
        }
    }

    // Block-level reduction for max and sum
    __shared__ float shared_max[BLOCK_SIZE];
    __shared__ float shared_sum[BLOCK_SIZE];
    shared_max[threadIdx.x] = thread_max;
    shared_sum[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            float max1 = shared_max[threadIdx.x];
            float max2 = shared_max[threadIdx.x + stride];
            float sum1 = shared_sum[threadIdx.x];
            float sum2 = shared_sum[threadIdx.x + stride];

            float new_max = fmaxf(max1, max2);
            float new_sum = 0.0f;
            if (new_max > -INFINITY) {
                new_sum = sum1 * expf(max1 - new_max) + sum2 * expf(max2 - new_max);
            }
            shared_max[threadIdx.x] = new_max;
            shared_sum[threadIdx.x] = new_sum;
        }
        __syncthreads();
    }

    float row_max = shared_max[0];
    float row_sum = shared_sum[0];
    float inv_row_sum = 1.0f / row_sum;

    float4* row_output_v4 = reinterpret_cast<float4*>(row_output);
    for (int i = threadIdx.x; i < dim_v4; i += BLOCK_SIZE) {
        float4 vals = row_input_v4[i];
        vals.x = expf(vals.x - row_max) * inv_row_sum;
        vals.y = expf(vals.y - row_max) * inv_row_sum;
        vals.z = expf(vals.z - row_max) * inv_row_sum;
        vals.w = expf(vals.w - row_max) * inv_row_sum;
        row_output_v4[i] = vals;
    }

    // Remaining elements
    for (int i = dim_v4 * 4 + threadIdx.x; i < dim; i += BLOCK_SIZE) {
        row_output[i] = expf(row_input[i] - row_max) * inv_row_sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto dim = x.size(1);
    auto y = torch::empty_like(x);

    const int num_blocks = batch_size;
    const int threads_per_block = BLOCK_SIZE;

    softmax_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        dim
    );

    return y;
}
"""

softmax_module = load_inline(
    name="softmax_hip",
    cpp_sources=softmax_cpp_source,
    functions=["softmax_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softmax_hip = softmax_module.softmax_hip

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softmax_hip(x)

