maxpool2d_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <algorithm>
#include <float.h>

#define TILE_W 16
#define TILE_H 16

__global__ void maxpool2d_kernel_shm(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int k_h, int k_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int H_out, int W_out)
{
    // Shared memory for the input tile. 
    // Max kernel size is 4, max stride is 1. 
    // For 16x16 output tile, we need (16*stride + (kernel-1)*dilation + 1)
    // Here stride=1, dilation=1, kernel=4. So 16+3 = 19.
    // To handle general cases, we'll size it based on common values or use a fixed large size.
    // Let's use 32x32 for safety as it fits in shared memory.
    __shared__ float shm_tile[32][32];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int nc_idx = blockIdx.z;

    int w_out_start = bx * TILE_W;
    int h_out_start = by * TILE_H;

    int h_in_start = h_out_start * stride_h - padding_h;
    int w_in_start = w_out_start * stride_w - padding_w;

    // Load input tile into shared memory
    // Each thread loads multiple elements
    int input_tile_h = TILE_H * stride_h + (k_h - 1) * dilation_h;
    int input_tile_w = TILE_W * stride_w + (k_w - 1) * dilation_w;

    // Safety check for shared memory size
    if (input_tile_h > 32) input_tile_h = 32;
    if (input_tile_w > 32) input_tile_w = 32;

    const float* input_ptr = input + (nc_idx * H * W);

    for (int i = ty; i < input_tile_h; i += TILE_H) {
        for (int j = tx; j < input_tile_w; j += TILE_W) {
            int h_in = h_in_start + i;
            int w_in = w_in_start + j;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                shm_tile[i][j] = input_ptr[h_in * W + w_in];
            } else {
                shm_tile[i][j] = -FLT_MAX;
            }
        }
    }
    __syncthreads();

    int w_out_idx = w_out_start + tx;
    int h_out_idx = h_out_start + ty;

    if (w_out_idx < W_out && h_out_idx < H_out) {
        float max_val = -FLT_MAX;
        for (int kh = 0; kh < k_h; ++kh) {
            for (int kw = 0; kw < k_w; ++kw) {
                float val = shm_tile[ty * stride_h + kh * dilation_h][tx * stride_w + kw * dilation_w];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
        output[(nc_idx * H_out + h_out_idx) * W_out + w_out_idx] = max_val;
    }
}

torch::Tensor maxpool2d_hip(
    torch::Tensor input,
    int kernel_size, int stride, int padding, int dilation) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int k_h = kernel_size;
    int k_w = kernel_size;
    int stride_h = stride;
    int stride_w = stride;
    int padding_h = padding;
    int padding_w = padding;
    int dilation_h = dilation;
    int dilation_w = dilation;

    int H_out = (H + 2 * padding_h - dilation_h * (k_h - 1) - 1) / stride_h + 1;
    int W_out = (W + 2 * padding_w - dilation_w * (k_w - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    dim3 block_size(TILE_W, TILE_H);
    dim3 num_blocks((W_out + TILE_W - 1) / TILE_W,
                    (H_out + TILE_H - 1) / TILE_H,
                    N * C);

    maxpool2d_kernel_shm<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        k_h, k_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        H_out, W_out
    );

    return output;
}
"""

maxpool2d_lib = load_inline(
    name="maxpool2d_shm",
    cpp_sources=maxpool2d_cpp_source,
    functions=["maxpool2d_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.maxpool2d_lib = maxpool2d_lib

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.maxpool2d_lib.maxpool2d_hip(x, self.kernel_size, self.stride, self.padding, self.dilation)

