    const int tid_b_row = tid / 32; // 0..7
    const int tid_b_col = (tid % 32) * 4; // 0, 4, ..., 124

    for (int k = 0; k < K; k += BK) {
        // Load sA
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            sA[tid_a_row][tid_a_col + i] = A[tid_a_row * K + (k + tid_a_col + i)];
        }

        // Load sB
