# Optimized GEMM using shared memory and register tiling
gemm_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16
#define MICRO_M 8
#define MICRO_N 8

__global__ void gemm_optimized_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    __shared__ float sA[TILE_M][TILE_K];
    __shared__ float sB[TILE_K][TILE_N];

    float rC[MICRO_M][MICRO_N] = {0.0f};
    float rA[MICRO_M];
    float rB[MICRO_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // tx, ty map to the threads in a TILE_M/MICRO_M x TILE_N/MICRO_N grid
    // Each thread handles a MICRO_M x MICRO_N block of C.
    // Total threads per block: (TILE_M/MICRO_M) * (TILE_N/MICRO_N) = (64/8) * (64/8) = 8 * 8 = 64 threads.

    int thread_row = ty * MICRO_M;
    int thread_col = tx * MICRO_N;

    for (int k_outer = 0; k_outer < N; k_outer += TILE_K) {
        // Load A into shared memory
        // Each thread needs to load (TILE_M * TILE_K) / 64 = 16 elements.
        for (int i = 0; i < (TILE_M * TILE_K) / 64; ++i) {
            int local_id = i * 64 + (ty * (TILE_N/MICRO_N) + tx);
            int row = local_id / TILE_K;
            int col = local_id % TILE_K;
            sA[row][col] = A[(by * TILE_M + row) * N + (k_outer + col)];
        }

        // Load B into shared memory
        // Each thread needs to load (TILE_K * TILE_N) / 64 = 16 elements.
        for (int i = 0; i < (TILE_K * TILE_N) / 64; ++i) {
            int local_id = i * 64 + (ty * (TILE_N/MICRO_N) + tx);
            int row = local_id / TILE_N;
            int col = local_id % TILE_N;
            sB[row][col] = B[(k_outer + row) * N + (bx * TILE_N + col)];
        }

        __syncthreads();

        for (int k_inner = 0; k_inner < TILE_K; ++k_inner) {
            for (int i = 0; i < MICRO_M; ++i) rA[i] = sA[thread_row + i][k_inner];
            for (int j = 0; j < MICRO_N; ++j) rB[j] = sB[k_inner][thread_col + j];

            for (int i = 0; i < MICRO_M; ++i) {
                for (int j = 0; j < MICRO_N; ++j) {
                    rC[i][j] += rA[i] * rB[j];
                }
            }
        }
        __syncthreads();
    }

    for (int i = 0; i < MICRO_M; ++i) {
        for (int j = 0; j < MICRO_N; ++j) {
            C[(by * TILE_M + thread_row + i) * N + (bx * TILE_N + thread_col + j)] = rC[i][j];
        }
    }
}

torch::Tensor gemm_optimized_hip(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 threads(TILE_N / MICRO_N, TILE_M / MICRO_M);
    dim3 blocks(N / TILE_N, N / TILE_M);

    gemm_optimized_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

