depthwise_conv2d_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define MAX_K 11
#define BLOCK_SIZE 256

__global__ void depthwise_conv2d_kernel_shm(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out) {

    extern __shared__ float shm[];
    float* s_weight = shm; // Size: K*K

    int nc = blockIdx.x; 
    int h_out = blockIdx.y;
    int w_out_start = blockIdx.z * BLOCK_SIZE;
    int w_out = w_out_start + threadIdx.x;

    int c = nc % C;
    int n = nc / C;

    // Load weight into shared memory
    if (threadIdx.x < K * K) {
        s_weight[threadIdx.x] = weight[c * K * K + threadIdx.x];
    }
    __syncthreads();

    if (w_out < W_out) {
        float sum = 0.0f;
        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_start + kh;
            if (h_in >= 0 && h_in < H) {
                const float* input_ptr = &input[((n * C + c) * H + h_in) * W];
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_start + kw;
                    if (w_in >= 0 && w_in < W) {
                        sum += input_ptr[w_in] * s_weight[kh * K + kw];
                    }
                }
            }
        }
        if (bias) {
            sum += bias[c];
        }
        output[((n * C + c) * H_out + h_out) * W_out + w_out] = sum;
    }
}

torch::Tensor depthwise_conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    at::optional<torch::Tensor> bias,
    int stride,
    int padding) {

    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int K = weight.size(2);

    int H_out = (H + 2 * padding - K) / stride + 1;
    int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    dim3 grid(N * C, H_out, (W_out + BLOCK_SIZE - 1) / BLOCK_SIZE);
    dim3 block(BLOCK_SIZE);

    float* bias_ptr = bias.has_value() ? bias.value().data_ptr<float>() : nullptr;
    int shm_size = K * K * sizeof(float);

    hipLaunchKernelGGL(depthwise_conv2d_kernel_shm, grid, block, shm_size, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        K, stride, padding,
        H_out, W_out);

    return output;
}
"""

depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
