#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Optimized kernel for tall-skinny-skinny-tall GEMM (small K)
// Each block computes a 64x64 tile of C.
// Each thread computes a 4x4 sub-tile of C.
// Block size: 16x16 threads.
__global__ void tall_skinny_matmul_v3_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    __shared__ float sA[64][32]; // Tiling over K in steps of 32
    __shared__ float sB[32][64];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int block_row = blockIdx.y * 64;
    int block_col = blockIdx.x * 64;

    float rC[4][4] = {0.0f};

    for (int k_offset = 0; k_offset < K; k_offset += 32) {
        // Load A and B into shared memory
        // Each of the 256 threads loads (64*32)/256 = 8 elements.

        // Load sA (64x32)
        // Thread (ty, tx) loads 8 elements of sA
        // ty: 0..15, tx: 0..15
        for (int i = 0; i < 8; ++i) {
            int local_id = (ty * 16 + tx) * 8 + i;
            int l_row = local_id / 32;
            int l_col = local_id % 32;
            if (block_row + l_row < M && k_offset + l_col < K) {
                sA[l_row][l_col] = A[(block_row + l_row) * K + (k_offset + l_col)];
            } else {
                sA[l_row][l_col] = 0.0f;
            }
        }

        // Load sB (32x64)
        for (int i = 0; i < 8; ++i) {
            int local_id = (ty * 16 + tx) * 8 + i;
            int l_row = local_id / 64;
            int l_col = local_id % 64;
            if (k_offset + l_row < K && block_col + l_col < N) {
                sB[l_row][l_col] = B[(k_offset + l_row) * N + (block_col + l_col)];
            } else {
                sB[l_row][l_col] = 0.0f;
            }
        }

        __syncthreads();

        // Compute 4x4 sub-tile
        for (int k = 0; k < 32 && (k_offset + k) < K; ++k) {
            float a_vals[4];
            float b_vals[4];
            for (int i = 0; i < 4; ++i) a_vals[i] = sA[ty * 4 + i][k];
            for (int j = 0; j < 4; ++j) b_vals[j] = sB[k][tx * 4 + j];

            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 4; ++j) {
                    rC[i][j] += a_vals[i] * b_vals[j];
                }
            }
        }
        __syncthreads();
    }

    // Write results to C
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            int row = block_row + ty * 4 + i;
            int col = block_col + tx * 4 + j;
            if (row < M && col < N) {
                C[row * N + col] = rC[i][j];
            }
        }
    }
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    if (A.is_cuda() == false) A = A.cuda();
    if (B.is_cuda() == false) B = B.cuda();

    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + 63) / 64, (M + 63) / 64);

    tall_skinny_matmul_v3_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
