#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_M 128
#define TILE_N 128
#define TILE_K 16
#define THREAD_M 8
#define THREAD_N 8

__global__ void matmul_optimized_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K, int N) {
    __shared__ float shA[TILE_K][TILE_M];
    __shared__ float shB[TILE_K][TILE_N];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes a THREAD_M x THREAD_N block of the output
    float res[THREAD_M][THREAD_N];
    for (int i = 0; i < THREAD_M; i++) {
        for (int j = 0; j < THREAD_N; j++) {
            res[i][j] = 0.0f;
        }
    }

    int thread_row = ty * THREAD_M;
    int thread_col = tx * THREAD_N;

    for (int k_offset = 0; k_offset < K; k_offset += TILE_K) {
        // Load into shared memory
        // Each block of (TILE_M/THREAD_M) x (TILE_N/THREAD_N) = 16x16 threads
        // needs to load 128x16 and 16x128 elements.
        // Each thread (out of 256) loads 128*16 / 256 = 8 elements of A and 8 elements of B.

        for (int i = 0; i < (TILE_M * TILE_K) / 256; i++) {
            int idx = i * 256 + ty * 16 + tx;
            int r = idx / TILE_K;
            int c = idx % TILE_K;
            int global_r = by * TILE_M + r;
            int global_c = k_offset + c;
            if (global_r < M && global_c < K)
                shA[c][r] = A[global_r * K + global_c];
            else
                shA[c][r] = 0.0f;
        }

        for (int i = 0; i < (TILE_K * TILE_N) / 256; i++) {
            int idx = i * 256 + ty * 16 + tx;
            int r = idx / TILE_N;
            int c = idx % TILE_N;
            int global_r = k_offset + r;
            int global_c = bx * TILE_N + c;
            if (global_r < K && global_c < N)
                shB[r][c] = B[global_r * N + global_c];
            else
                shB[r][c] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_K; k++) {
            float a_vals[THREAD_M];
            float b_vals[THREAD_N];
            for (int i = 0; i < THREAD_M; i++) a_vals[i] = shA[k][thread_row + i];
            for (int j = 0; j < THREAD_N; j++) b_vals[j] = shB[k][thread_col + j];

            for (int i = 0; i < THREAD_M; i++) {
                for (int j = 0; j < THREAD_N; j++) {
                    res[i][j] += a_vals[i] * b_vals[j];
                }
            }
        }
        __syncthreads();
    }

    for (int i = 0; i < THREAD_M; i++) {
        for (int j = 0; j < THREAD_N; j++) {
            int global_r = by * TILE_M + thread_row + i;
            int global_c = bx * TILE_N + thread_col + j;
            if (global_r < M && global_c < N) {
                C[global_r * N + global_c] = res[i][j];
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    matmul_optimized_kernel<<<num_blocks, block_size>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
"""

