#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define THREADS_PER_BLOCK 256
#define WARP_SIZE 64

__global__ void mv_kernel_unrolled(const float4* __restrict__ A, const float4* __restrict__ B, float* __restrict__ C, int M, int K_vec) {
    int row = blockIdx.x;
    if (row >= M) return;

    float sum = 0.0f;
    int tid = threadIdx.x;

    // Unroll by 4 for more ILP
    int k = tid;
    for (; k + 3 * THREADS_PER_BLOCK < K_vec; k += 4 * THREADS_PER_BLOCK) {
        float4 a0 = A[row * K_vec + k];
        float4 b0 = B[k];
        sum += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;

        float4 a1 = A[row * K_vec + k + THREADS_PER_BLOCK];
        float4 b1 = B[k + THREADS_PER_BLOCK];
        sum += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;

        float4 a2 = A[row * K_vec + k + 2 * THREADS_PER_BLOCK];
        float4 b2 = B[k + 2 * THREADS_PER_BLOCK];
        sum += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;

        float4 a3 = A[row * K_vec + k + 3 * THREADS_PER_BLOCK];
        float4 b3 = B[k + 3 * THREADS_PER_BLOCK];
        sum += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
    }

    for (; k < K_vec; k += THREADS_PER_BLOCK) {
        float4 a = A[row * K_vec + k];
        float4 b = B[k];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    // Block reduction using shared memory and warp shuffle
    __shared__ float shared_sum[THREADS_PER_BLOCK / WARP_SIZE];

    int warpId = tid / WARP_SIZE;
    int lane = tid % WARP_SIZE;

    float val = sum;
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);

    if (lane == 0) shared_sum[warpId] = val;
    __syncthreads();

    if (tid < WARP_SIZE) {
        val = (tid < (THREADS_PER_BLOCK / WARP_SIZE)) ? shared_sum[tid] : 0.0f;
        for (int offset = (THREADS_PER_BLOCK / WARP_SIZE) / 2; offset > 0; offset /= 2)
            val += __shfl_down(val, offset);
        if (tid == 0) C[row] = val;
    }
}

torch::Tensor mv_hip(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto C = torch::empty({M, 1}, A.options());

    int K_vec = K / 4;

    mv_kernel_unrolled<<<M, THREADS_PER_BLOCK>>>(
        (const float4*)A.data_ptr<float>(),
        (const float4*)B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K_vec
    );

    return C;
}
"""

