#define TILE_W 16
#define TILE_H 16

__global__ void depthwise_conv2d_kernel_tiled(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out) {

    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int c = blockIdx.x % C;
    int n = blockIdx.x / C;
    int h_out_start = blockIdx.y * TILE_H;
    int w_out_start = blockIdx.z * TILE_W;

    int h_out = h_out_start + ty;
    int w_out = w_out_start + tx;

    // Use shared memory for weight
    __shared__ float s_weight[121]; // Max K=11
    if (ty == 0 && tx < K * K) {
        s_weight[tx] = weight[c * K * K + tx];
    }
    __syncthreads();

    if (h_out < H_out && w_out < W_out) {
        float sum = 0.0f;
        int h_in_base = h_out * stride - padding;
        int w_in_base = w_out * stride - padding;

        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_in_base + kh;
            if (h_in >= 0 && h_in < H) {
                const float* input_ptr = &input[((n * C + c) * H + h_in) * W];
                for (int kw = 0; kw < K; ++kw) {
                    int w_in = w_in_base + kw;
                    if (w_in >= 0 && w_in < W) {
                        sum += input_ptr[w_in] * s_weight[kh * K + kw];
                    }
                }
            }
        }
        if (bias) {
            sum += bias[c];
        }
        output[((n * C + c) * H_out + h_out) * W_out + w_out] = sum;
    }
}

