gemm_cpp_source = """
#include <hip/hip_runtime.h>
#include <hipblas/hipblas.h>
#include <torch/extension.h>

// Handle to hipBLAS
static hipblasHandle_t handle = nullptr;

torch::Tensor hipblas_gemm_hip(torch::Tensor A, torch::Tensor B) {
    if (handle == nullptr) {
        hipblasCreate(&handle);
    }

    int m = A.size(0);
    int k = A.size(1);
    int n = B.size(1);

    auto C = torch::empty({m, n}, A.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    // hipBLAS uses column-major order.
    // For C = A * B in row-major:
    // C^T = (A * B)^T = B^T * A^T
    // If we treat row-major matrices as column-major, then A is A^T and B is B^T.
    // So we want to compute B * A = (B^T * A^T)^T = (A * B)
    // Here A is (m, k), B is (k, n), C is (m, n) in row-major.
    // In column-major, A_cm is (k, m), B_cm is (n, k), C_cm is (n, m).
    // So we want C_cm = B_cm * A_cm
    // where B_cm is (n, k) and A_cm is (k, m).

    hipblasSgemm(handle,
                 HIPBLAS_OP_N, HIPBLAS_OP_N,
                 n, m, k,
                 &alpha,
                 B.data_ptr<float>(), n,
                 A.data_ptr<float>(), k,
                 &beta,
                 C.data_ptr<float>(), n);

    return C;
}
"""

