__global__ void gelu_kernel_v8(const float* __restrict__ input, float* __restrict__ output, int n) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 8;
    if (idx + 7 < n) {
        float4 in1 = reinterpret_cast<const float4*>(input)[idx / 4];
        float4 in2 = reinterpret_cast<const float4*>(input)[idx / 4 + 1];
        float4 out1, out2;

        out1.x = 0.5f * in1.x * (1.0f + erff(in1.x * 0.7071067811865475f));
        out1.y = 0.5f * in1.y * (1.0f + erff(in1.y * 0.7071067811865475f));
        out1.z = 0.5f * in1.z * (1.0f + erff(in1.z * 0.7071067811865475f));
        out1.w = 0.5f * in1.w * (1.0f + erff(in1.w * 0.7071067811865475f));

        out2.x = 0.5f * in2.x * (1.0f + erff(in2.x * 0.7071067811865475f));
        out2.y = 0.5f * in2.y * (1.0f + erff(in2.y * 0.7071067811865475f));
        out2.z = 0.5f * in2.z * (1.0f + erff(in2.z * 0.7071067811865475f));
        out2.w = 0.5f * in2.w * (1.0f + erff(in2.w * 0.7071067811865475f));

        reinterpret_cast<float4*>(output)[idx / 4] = out1;
        reinterpret_cast<float4*>(output)[idx / 4 + 1] = out2;
    } else {
        for (int i = idx; i < n; ++i) {
            float x = input[i];
            output[i] = 0.5f * x * (1.0f + erff(x * 0.7071067811865475f));
        }
    }
