__global__ void tall_skinny_matmul_v4_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int row = blockIdx.x;
    if (row >= M) return;

    // Use shared memory for row of A
    __shared__ float sA[32];
    for (int k = threadIdx.x; k < K; k += blockDim.x) {
        sA[k] = A[row * K + k];
    }
    __syncthreads();

    for (int col = threadIdx.x; col < N; col += blockDim.x) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += sA[k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

