#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void __launch_bounds__(256) optimized_gemm_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int N) {

    const int BM = 128;
    const int BN = 128;
    const int BK = 8;
    const int TM = 8;
    const int TN = 8;

    const int thread_y = threadIdx.y;
    const int thread_x = threadIdx.x;
    const int block_y = blockIdx.y;
    const int block_x = blockIdx.x;

    __shared__ float sA[BM][BK];
    __shared__ float sB[BK][BN];

    float rC[TM][TN];
    for(int i=0; i<TM; ++i) for(int j=0; j<TN; ++j) rC[i][j] = 0.0f;

    float rA[TM];
    float rB[TN];

    const int tid = thread_y * 16 + thread_x;
    const int tid_a_row = tid / 2; 
    const int tid_a_col = (tid % 2) * 4; 
    const int tid_b_row = tid / 32; 
    const int tid_b_col = (tid % 32) * 4; 

    for (int k = 0; k < K; k += BK) {
        // Use float4 for vectorized loads
        float4* sA_ptr = (float4*)&sA[tid_a_row][tid_a_col];
        const float4* A_ptr = (const float4*)&A[(block_y * BM + tid_a_row) * K + (k + tid_a_col)];
        *sA_ptr = *A_ptr;

        float4* sB_ptr = (float4*)&sB[tid_b_row][tid_b_col];
        const float4* B_ptr = (const float4*)&B[(k + tid_b_row) * N + (block_x * BN + tid_b_col)];
        *sB_ptr = *B_ptr;

        __syncthreads();

        #pragma unroll
        for (int ki = 0; ki < BK; ++ki) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) rA[i] = sA[thread_y * TM + i][ki];
            #pragma unroll
            for (int j = 0; j < TN; ++j) rB[j] = sB[ki][thread_x * TN + j];

            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    rC[i][j] += rA[i] * rB[j];
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; j += 4) {
            float4* C_ptr = (float4*)&C[(block_y * BM + thread_y * TM + i) * N + (block_x * BN + thread_x * TN + j)];
            float4 val;
            val.x = rC[i][j];
            val.y = rC[i][j+1];
            val.z = rC[i][j+2];
            val.w = rC[i][j+3];
            *C_ptr = val;
        }
    }
}

torch::Tensor optimized_gemm_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::empty({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid(N / 128, M / 128);

    optimized_gemm_kernel<<<grid, block>>>(
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K, N);

    return C;
}
"""

