    int m = A.size(0);
    int k = A.size(1);
    int n = B.size(1);

    auto C = torch::empty({m, n}, A.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    // hipBLAS uses column-major order.
    // For C = A * B in row-major:
    // C^T = (A * B)^T = B^T * A^T
    // Treat row-major matrices as column-major, then A is A^T and B is B^T.
    // So we want to compute B * A = (B^T * A^T)^T = (A * B)
    // where B_cm is (n, k) and A_cm is (k, m).

    hipblasSgemm(handle,
                 HIPBLAS_OP_N, HIPBLAS_OP_N,
                 n, m, k,
                 &alpha,
                 B.data_ptr<float>(), n,
                 A.data_ptr<float>(), k,
                 &beta,
                 C.data_ptr<float>(), n);

    return C;
}
